# -*- coding: utf-8 -*-
"""天子之義第二 — 日本語訳。"""

TITLE = '第二篇　天子之義（てんしのぎ）'
HEAD = '''十五段。全書で最も長く、史料としての価値も最も高い一篇である。題は「天子の義」だが、説くところは教化と容儀である。士は先に教えを受けなければ用いることができない。貴賤・徳義・材技・勇力はそれぞれ分を守って侵しあわない、「ゆえに力同じくして意和す」。中ほどには三代の対照が四組続く——有虞氏・夏・殷・周がどこで誓ったか、刃をどこまで用いたか、賞をどこで与え戮をどこで行ったか。戎車の名は何か、旂は何色か、旗章は日月か虎か龍か。三代の軍制を調べる者が避けて通れない数段であり、『漢書』芸文志がこの書を礼類に入れた理由でもある。全篇の要は二度くりかえされる一句——<i>国容は軍に入らず、軍容は国に入らず</i>。取り違えれば「軍容、国に入れば民徳廃れ、国容、軍に入れば民徳弱る」。末の二段は急に柔らかくなる。大勝しても賞さず、大敗しても誅さず、上下ともに非をおのれに帰す。「譲の至りなり」。'''

PARA = {
 'p2-1': '天子の義は、必ず純（もっぱ）ら天地に法（のっと）り、先聖に観る。士庶の義は、必ず父母に奉じ、君長に正す。ゆえに明君ありといえども、士、先に教えられざれば用いることはできない。（「純」は雑りけのないこと。「取灋」の「灋」は「法」の古文。本書は同じ一文のなかで「灋」「法」の両形を兼ね用い、二旧本も同じなので、本頁では統一しない（巻末参照）。上に天地、下に父母、あいだに君長。三層を言い終えて「先に教えざれば用うべからず」に落ちる——全篇の話頭はここから起こる。）',
 'p2-2': '古、民を教えるには、必ず貴賤の倫経（順序・きまり）を立てて互いに陵がせず、徳義は互いに踰えず、材技は互いに掩わず、勇力は互いに犯さない。ゆえに力を同じくして意が和する。（四庫本は「故方同而意和」に作る。三つの「相ひ……ず」が題目であり、次段がそれに一つずつ答える。）',
 'p2-3': '古、国容は軍に入らず、軍容は国に入らなかった。ゆえに徳義は互いに踰えなかった。上は伐（ほこ）らざる士を貴ぶ。伐らざる士は上の器である。もし伐らなければ求めるところがなく、求めるところがなければ争わない。国中の聴訟は必ずその情を得、軍旅の聴断は必ずその宜を得る。ゆえに材技は互いに掩わなかった。命に従うを士の上賞とし、命を犯すを士の上戮とした。ゆえに勇力は互いに犯さなかった。（「国容」「軍容」は朝廷と軍中の二つの作法。「上の器」はその人材こそ用いるに足るということ。前段が立てた三つの題目に、この段が順に答えている。）',
 'p2-4': 'すでに教えをその民に致したのち、謹んで選んでこれを使う。事、極めて修まれば百官足り、教え、極めて省（はぶ）ければ民は良に興り、習慣が成れば民はその俗を体（からだ）とする。教化の至りである。（「習貫」の「貫」は慣。「民、俗を体とす」——三句のうち最後が最も深く、直訳が最もよい。）',
 'p2-5': '古、敗走する者を追うこと遠からず、退く者に迫ること及ばず。遠く追わなければ誘われにくく、迫りすぎなければ陥れられにくい。礼を以て固めとし、仁を以て勝ちとする。すでに勝ったのちも、その教えは繰り返し行える。だから君子はこれを貴んだ。（四庫本は「縦緩」を「縦綏」に作る（『仁本』の「縦綏三舎を過ぎず」と同字）。この段は『仁本』の「百歩を過ぎず」に、きわめて実際的な理由を添えている——礼のためだけではなく、伏兵にかからぬためである。）',
 'p2-6': '有虞氏は国中で戒め、民にその命を体させようとした。夏后氏は軍中で誓い、民に先だってその慮りを成さしめようとした。殷は軍門の外で誓い、民に先に意を定めて事を行わせようとした。周は刃を交えようとして誓い、民の志を致（きわ）めた。夏后氏はその徳を正して、いまだ兵の刃を用いなかった。ゆえにその兵は雑らなかった。殷は義であって、はじめて兵の刃を用いた。周は力であって、兵の刃を用い尽くした。夏は朝に賞して善を貴び、殷は市に戮して不善を威し、周は朝に賞し市に戮して君子を勧め小人を懼れさせた。三王がその徳を彰らかにしたのは一つである。（「誓」は出兵前の宣誓で、『書経』の甘誓・湯誓・牧誓がまさに三代の三篇。四庫本は「先意以行事也」を「以待事也」に作る。誓の場所が国中から軍門、さらに交刃の際へと移ってゆくのは見どころで、後世になるほど刃の近くまで行かねば気が立たない。）',
 'p2-7': '兵（武器）は雑らなければ利あらず。長兵は以て衛（まも）り、短兵は以て守る。長すぎれば犯しにくく、短すぎれば及ばない。軽すぎれば鋭く、鋭ければ乱れやすい。重すぎれば鈍く、鈍ければ済（な）らない。（前段の「その兵雑らず」を裏返している。あちらでは夏后氏の徳であったものが、こちらでは器の欠点になる。武器そのものを論ずるのは全書でこの一段だけである。）',
 'p2-8': '戎車は、夏后氏これを鉤車といい、正を先とした。殷はこれを寅車といい、疾を先とした。周はこれを元戎といい、良を先とした。（「元戎」は『詩経』小雅・六月の「元戎十乗、以て先んじて行を啓く」。三代がそれぞれ一字で車名を立てる——正・疾・良。）',
 'p2-9': '旂（き）は、夏后氏は玄（くろ）を首とした。人の執るところである。殷は白、天の義である。周は黄、地の道である。（「旂」は鈴のついた旗。四庫本は「人之執也」を「人之埶也」に作る（「埶」は「勢」）。夏は黒、殷は白、周は赤を尚ぶというのが通説で、ここに周を黄とするのは土徳の説に合う。）',
 'p2-10': '旗章は、夏后氏は日月を以てし、明を尚ぶ。殷は虎を以てし、白戎である。周は龍を以てし、文を尚ぶ。（底本と影宋鈔本はともに「殷、虎を以てす、白戎なり」に作るが、四庫本は「尚威なり」に作り、前後の「尚明」「尚文」と一類を成して文意が明らかである。本頁の改字は二本一致を要件とするので、ここは底本のままとした。「白戎」を強いて解けば、白は西方の色、戎は兵事、虎は西方白虎の象ということになる。両説を並べて読者に委ねる。）',
 'p2-11': '師（いくさ）が威を務めすぎれば民は詘（くっ）し、威が少なければ民は用に堪えない。上が民を使ってその義を得ず、百姓がその叙（ついで）を得ず、技用がその利を得ず、牛馬がその任を得ず、有司がこれを陵ぐ——これを多威という。多威なれば民は詘する。上が徳を尊ばずして詐慝を任じ、道を尊ばずして勇力を任じ、命に用うるを貴ばずして命を犯すを貴び、善行を貴ばずして暴行を貴び、有司に陵がれる——これを少威という。少威なれば民は用に堪えない。軍旅は舒（ゆる）やかなるを主とする。舒やかなれば民力は足る。兵を交え刃を致すときでさえ、徒は趨らず、車は馳せず、敗走を追うにも列を踰えない。ゆえに乱れない。軍旅の固さは、行列の政を失わず、人馬の力を絶やさず、遅速が誡命を過ぎないことにある。（「詘」は屈。「叙」は順序。「舒」は全書が治軍について挙げる最も重い一字。「誡命」の「誡」を影宋鈔本は「誠」に作る。多威と少威という相反する二つの病に、薬は一つ——舒。）',
 'p2-12': '古、国容は軍に入らず、軍容は国に入らなかった。軍容が国に入れば民徳は廃れ、国容が軍に入れば民徳は弱る。ゆえに国にあっては言は文（あや）やかに語は温かく、朝にあっては恭しく遜（へりくだ）り、己を修めて人を待ち、召されなければ至らず、問われなければ言わず、進むに難く退くに易い。軍にあっては抗（こう）して立ち、行（こう）にあっては遂げて果たし、介（よろい）の者は拝せず、兵車では式（しょく、軾に手をかける礼）せず、城上では趨らず、危事には歯（よわい）を論じない。ゆえに礼と法とは表裏であり、文と武とは左右である。（四庫本は「在行遂而果」を「在行逐而果」に作る。第三段の一句をここで一篇に展べ、末の二句が全篇の断案となる——礼と法、文と武は二つのものではなく、一つのものの二つの面である。）',
 'p2-13': '古、賢王は民の徳を明らかにし民の善を尽くさせた。ゆえに廃れる徳なく、軽んぜられる民なく、賞は生ずるところなく、罰は試みるところがなかった。有虞氏は賞さず罰せずして民は用いられた。徳の至りである。夏は賞して罰せず、教の至りである。殷は罰して賞せず、威の至りである。周は賞罰を以てした、徳の衰えである。賞は時を踰えない、民に善を為すことの利を速やかに得させるためである。罰は列を遷さない、民に不善を為すことの害を速やかに覩（み）させるためである。大捷にも賞さず、上下ともに善を伐らない。上がもし善を伐らなければ驕らず、下がもし善を伐らなければ等（きそ）うことがない。上下、善を伐らざることかくのごとくであれば、譲の至りである。大敗にも誅さず、上下ともに不善を己に在りとする。上がもし不善を己に在りとすれば必ずその過ちを悔い、下がもし不善を己に在りとすれば必ずその罪を遠ざける。上下、悪を分かつことかくのごとくであれば、これも譲の至りである。（「罰は列を遷さず」は隊列から引き出さずその場で罰すること。三つの「己」を影宋鈔本はいずれも「已」に作る（鈔胥の誤り）。「大捷にも賞さず、大敗にも誅さず」は全書で最も兵書らしくなく、また最も兵書らしい一段である——この一戦ではなく、次の一戦を扱っているからだ。）',
 'p2-14': '古、戍（まも）りの兵は三年のあいだ再び興さなかった。民の労を覩たからである。上下が互いにこう報いあうならば、和の至りである。（影宋鈔本は「戍兵」を「戍軍」に、四庫本は「不興」を「不典」に作る。）',
 'p2-15': '意を得れば愷歌（がいか）して喜びを示し、伯（へい、兵事）を偃（ふ）せ霊台を築いて民の労に答え、休（いこ）いを示す。（「偃伯」の「伯」は覇と読み、兵を息めること。「霊台」は『詩経』大雅・霊台、文王の台で民と楽しむ場所。一篇の終わりに残るのは二つの動作だけ——歌うことと、建てること。）',
}
